SELECT "ART_link", 
    CASE WHEN env_handling_sensitivity->'environment'->>'light' IS NOT NULL AND env_handling_sensitivity->'environment'->>'light' != '' THEN 1 END as light_w
FROM "SensitivityData" WHERE "ART_link" = 'ART54317';

SELECT er."case_link", AVG(er."tempVar24") as avg_tempvar, AVG(er."RHvar") as avgrhvar 
FROM "EnvironmentalReadingsCore" er 
GROUP BY er."case_link" LIMIT 5;

SELECT ac."ARTregID", ac."DYNASTY", ar."HIST_sign", ar."rating_profile"->>'research_score' as research_score 
FROM "ArtifactsCore" ac
JOIN "ArtifactRatings" ar ON ac."ARTregID" = ar."ART_link";

